style.css:
@-moz-document domain("pekora.zip"), domain("www.pekora.zip") {
.imgDesktop-0-2-9 {
  width: 122px;
  height: 40px;
  display: none;
  max-width: 122px;
  min-width: 122px;
  background-size: 100% auto;
  background-image: url("https://web.archive.org/web/20160628094025im_/http://static.rbxcdn.com/images/Logo/roblox_logo.svg");
  background-repeat: no-repeat;
  background-position: center;
}

@media(min-width: 1325px) {
  .imgDesktop-0-2-9 {
    display: block;
  }
}

.imgMobile-0-2-10 {
  width: 30px;
  height: 30px;
  display: block;
  margin-left: 6px;
  background-size: 30px;
  background-image: url("https://web.archive.org/web/20250826011158if_/https://www.pekora.zip/favicon.ico");
  background-repeat: no-repeat;
  background-position: center;
}

@media(min-width: 1325px) {
  .imgMobile-0-2-10 {
    display: none;
  }
}
}
